#pragma once
// namelist.atmosphere as MPAS-Atmosphere reads it: every option of the Registry's namelist records
// (src/core_atmosphere/Registry.xml nml_record / nml_option; table src/core/namelist_table.inc, generated by
// tools/gen_namelist_table.py) is known, and an option a file leaves out takes the Registry default
// (gen_inc.c:810-826; a real default is compiled as printf %lf of it). A name that is not an option of its record
// is an error (MPAS's read(unit, nml=...) fails, gen_inc.c:857, 910-911). Every option's value, given or default,
// must be one a verified MPAS reference runs with: any other value has no verified port and is a hard error naming
// the option (CONSTITUTION.md 2.4). Without a namelist file every option takes its Registry default, which fails
// for the options whose default no reference runs with (config_dt, ...).
#include <map>
#include <string>

#include "core/precision.hpp"

namespace cppmpas {

struct InitConfig {
  real config_coef_3rd_order = 0.25;              // Registry.xml:244
  bool config_h_ScaleWithMesh = true;              // Registry.xml:274
  real config_zd = 22000.0;                        // Registry.xml:291
  real config_xnutr = 0.2;                         // Registry.xml:296
  real config_epssm_minimum = 0.1;                 // Registry.xml:326
  real config_epssm_maximum = 0.5;                 // Registry.xml:331
  real config_epssm_transition_bottom_z = 30000.;  // Registry.xml:336
  real config_epssm_transition_top_z = 50000.;     // Registry.xml:341
  bool config_do_restart = false;                  // Registry.xml:395
  bool config_do_DAcycling = false;                // Registry.xml:400
  real config_len_disp = 0.0;                      // Registry.xml:174
  std::string config_start_time = "2010-10-23_00:00:00";  // Registry.xml:84
  real config_epssm = 0.0;                         // Registry.xml:259
  bool config_positive_definite = false;           // Registry.xml:234
  bool config_apply_lbcs = false;                  // Registry.xml:349
};

// One assignment of a namelist file: its record and the value as written (quotes removed, quoted = it had them).
struct NmlValue {
  std::string record, text;
  bool quoted = false;
};
// The assignments of a Fortran namelist file, by lower-case option name; unknown records / options are errors.
std::map<std::string, NmlValue> read_namelist_file(const std::string& path);
// Every Registry option with its effective value (the file's or the Registry default), normalised, each checked
// against the values of the verified references (empty path: the Registry defaults).
std::map<std::string, std::string> effective_namelist(const std::string& path);
// InitConfig from a namelist.atmosphere file (empty path: the Registry defaults), after effective_namelist's checks.
InitConfig read_init_config(const std::string& path);

}  // namespace cppmpas
